body.script:
//
(function(){
  var root=document.documentElement;
  var saved=localStorage.getItem('open-debug-theme');
  if(saved){root.setAttribute('data-theme',saved);}
  document.querySelectorAll('.theme-toggle').forEach(function(btn){btn.addEventListener('click',function(){var next=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',next);localStorage.setItem('open-debug-theme',next);});});
  document.querySelectorAll('.menu-toggle').forEach(function(btn){btn.addEventListener('click',function(){document.body.classList.toggle('mobile-nav-open');});});
  var panel=document.getElementById('search-panel');
  document.querySelectorAll('.search-toggle').forEach(function(btn){btn.addEventListener('click',function(){panel&&panel.classList.add('open');panel&&panel.setAttribute('aria-hidden','false');});});
  document.querySelectorAll('.search-close').forEach(function(btn){btn.addEventListener('click',function(){panel&&panel.classList.remove('open');panel&&panel.setAttribute('aria-hidden','true');});});
  var notice=document.getElementById('cookie-notice');
  if(notice&&!localStorage.getItem('open-debug-cookie-ok')){notice.classList.add('show');}
  document.querySelectorAll('[data-cookie-ok]').forEach(function(btn){btn.addEventListener('click',function(){localStorage.setItem('open-debug-cookie-ok','1');notice&&notice.classList.remove('show');});});
  document.querySelectorAll('a.gated-link').forEach(function(link){link.addEventListener('click',function(evt){if(link.dataset.ready==='true'){return;}evt.preventDefault();var box=document.createElement('span');box.className='gate';box.textContent='Preparing link...';link.insertAdjacentElement('afterend',box);setTimeout(function(){link.dataset.ready='true';box.textContent='Link ready. Click again to continue.';},3000);});});
})();
  //
